#!/bin/bash
set -e

echo "============================================"
echo "  Laravel API - Automated Setup Script"
echo "============================================"
echo ""

# Define colors for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
NC='\033[0m' # No Color

# Working directory
LARAVEL_DIR="/var/www/laravel-api"
cd "$LARAVEL_DIR"

# Step 1: Ensure .env file exists
# NOTE: laravel-api/.env is generated by setup-env.sh on the HOST before `docker compose up`.
# The entrypoint should NOT overwrite it - setup-env.sh already injected correct credentials.
# Only create a fallback from .env.example if .env is completely missing.
echo -e "${YELLOW}[1/6] Checking .env file...${NC}"
if [ -f ".env" ] && grep -q "APP_KEY=base64:" ".env"; then
    echo -e "${GREEN}  ✓ .env already exists with valid APP_KEY${NC}"
elif [ -f ".env.example" ]; then
    echo -e "${BLUE}  -> .env missing or incomplete. Creating from .env.example as fallback...${NC}"
    cp .env.example .env
    echo -e "${YELLOW}  ⚠ WARNING: Using placeholder credentials from .env.example.${NC}"
    echo -e "${YELLOW}    Run 'bash setup-env.sh' on host then restart the container.${NC}"
else
    echo -e "${RED}  ✗ ERROR: Neither .env nor .env.example found!${NC}"
    exit 1
fi
echo ""


# Step 2: Fresh Composer Install
echo -e "${YELLOW}[2/6] Managing Composer packages...${NC}"

if [ ! -d "vendor" ]; then
    echo -e "${BLUE}  -> No vendor directory found, will perform fresh install...${NC}"
else
    echo -e "${BLUE}  -> Vendor directory exists, will update...${NC}"
fi

echo -e "${BLUE}  -> Configuring Composer settings...${NC}"
composer config --global process-timeout 600
composer config --global cache-files-maxsize 512MiB

echo -e "${BLUE}  -> Installing dependencies (this may take a while)...${NC}"
if composer install \
    --no-interaction \
    --prefer-dist \
    --optimize-autoloader \
    --ignore-platform-req=ext-awscrt; then
    
    echo -e "${GREEN}  ✓ Composer packages installed successfully${NC}"
else
    echo -e "${RED}  ✗ ERROR: Composer install failed!${NC}"
    exit 1
fi
echo ""


# Step 3: Wait for database to be ready
echo -e "${YELLOW}[3/6] Waiting for database to be ready...${NC}"
MAX_RETRIES=30
RETRY_COUNT=0

while [ $RETRY_COUNT -lt $MAX_RETRIES ]; do
    if pg_isready -h "${DB_HOST}" -p "${DB_PORT}" -U "${DB_USERNAME}" > /dev/null 2>&1; then
        echo -e "${GREEN}  ✓ Database is ready${NC}"
        break
    fi
    
    RETRY_COUNT=$((RETRY_COUNT + 1))
    echo -e "${BLUE}  -> Waiting for database... (${RETRY_COUNT}/${MAX_RETRIES})${NC}"
    sleep 2
done

if [ $RETRY_COUNT -eq $MAX_RETRIES ]; then
    echo -e "${RED}  ✗ ERROR: Database not ready after ${MAX_RETRIES} attempts${NC}"
    exit 1
fi
echo ""

# Step 4: Generate application key (only if not already set)
echo -e "${YELLOW}[4/6] Generating application key...${NC}"
if grep -q "APP_KEY=base64:" .env; then
    echo -e "${GREEN}  ✓ Application key already exists${NC}"
else
    echo -e "${BLUE}  -> Running: php artisan key:generate${NC}"
    php artisan key:generate --force
    if [ $? -eq 0 ]; then
        echo -e "${GREEN}  ✓ Application key generated${NC}"
    else
        echo -e "${RED}  ✗ ERROR: Key generation failed${NC}"
        exit 1
    fi
fi
echo ""

# Step 5: Set proper permissions
echo -e "${YELLOW}[5/6] Setting file permissions...${NC}"
chown -R www-data:www-data storage bootstrap/cache
chmod -R 775 storage bootstrap/cache
echo -e "${GREEN}  ✓ Permissions set${NC}"
echo ""

# Step 6: Run project setup (migrations + seeds) - ONLY if DB is empty
echo -e "${YELLOW}[6/6] Running project setup (Migrate & Seed)...${NC}"

# Kiểm tra xem database đã có bảng nào chưa
TABLE_COUNT=$(PGPASSWORD="${DB_PASSWORD}" psql -h "${DB_HOST}" -p "${DB_PORT}" -U "${DB_USERNAME}" -d "${DB_DATABASE}" -t -c "SELECT count(*) FROM information_schema.tables WHERE table_schema = 'public';" | xargs)

if [ "$TABLE_COUNT" -eq 0 ]; then
    echo -e "${BLUE}  -> Database is empty. Performing initial migration...${NC}"
    if php artisan migrate --force; then
        echo -e "${GREEN}  ✓ Database migration completed successfully${NC}"
        
        # Chỉ Seed nếu đây là lần đầu dựng DB
        echo -e "${BLUE}  -> Running initial data seeding...${NC}"
        php artisan db:seed --force
        echo -e "${GREEN}  ✓ Initial seeding completed successfully${NC}"
    else
        echo -e "${RED}  ✗ ERROR: Initial migration failed!${NC}"
        exit 1
    fi
else
    echo -e "${GREEN}  ✓ Database already initialized (Tables: $TABLE_COUNT). Skipping setup.${NC}"
fi
echo ""

# Final summary
echo "============================================"
echo -e "${GREEN}  Setup Complete! Laravel API is ready.${NC}"
echo "============================================"
echo ""
echo "Summary:"
echo "  ✓ Environment file: .env"
echo "  ✓ Composer packages: installed"
echo "  ✓ Application key: ready"
echo "  ✓ Database: migrations completed"
echo "  ✓ Permissions: synced"
echo ""
echo "============================================"
echo "  Starting service..."
echo "============================================"
echo ""

# Execute the command passed to the container
# If no command is provided, default to php-fpm
if [ $# -eq 0 ]; then
    echo "No command provided, starting PHP-FPM..."
    exec php-fpm
else
    echo "Executing command: $@"
    exec "$@"
fi
